// Generated by scripts/stitch-to-react.mjs from Stitch screen "Dev in_ 등급 및 뱃지 (19번)" (8afd33f52c3d486a8ea882836f91447a).
// REQ-MYPAGE-005 (#31): A안 — 등급은 채택된 답변 수 기준, 뱃지 6종, 조회할 때 계산 (docs/api.md 3장).
// 시안의 활동 점수·점수 획득 기준·상위 %·획득일·등급 혜택은 A안에 없어서 뺐다. 헤더는 공통 components/Header.
import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { getErrorMessage } from "../api/client";
import { getMyGrade, type Badge, type Grade, type GradeInfo } from "../api/mypage";
import { BADGE_ICON, GRADE_MIN_ACCEPTED, GRADE_NAME, GRADE_ORDER, gradeLevel } from "../components/gradeBadge";
import Header from "../components/Header";
import { useAuth } from "../hooks/useAuth";
import "./GradesBadges.css";

// Page-local styles from the Stitch <head>; mounted only while this page is shown.
const css =
  "@import url('https://cdn.jsdelivr.net/gh/orioncactus/pretendard/dist/web/static/pretendard.css');\n    body {\n      font-family: 'Pretendard', -apple-system, BlinkMacSystemFont, system-ui, Roboto, sans-serif;\n    }\n  \n\n    .brutal-border {\n      border: 2px solid #0F172A;\n    }\n    .brutal-card {\n      background-color: #FFFFFF;\n      border: 2px solid #0F172A;\n      box-shadow: 4px 4px 0px 0px #0F172A;\n    }";

// 등급별 메달 색 (시안의 실버 스타일을 등급마다 바꿔 쓴다)
const MEDAL_STYLE: Record<Grade, { circle: string; icon: string; text: string; bar: string; row: string }> = {
  BRONZE: {
    circle: "bg-amber-100",
    icon: "text-amber-700",
    text: "text-amber-800",
    bar: "bg-amber-600",
    row: "text-amber-800",
  },
  SILVER: {
    circle: "bg-slate-200",
    icon: "text-slate-500",
    text: "text-slate-600",
    bar: "bg-slate-600",
    row: "text-slate-600",
  },
  GOLD: {
    circle: "bg-yellow-100",
    icon: "text-yellow-500",
    text: "text-yellow-700",
    bar: "bg-yellow-500",
    row: "text-yellow-600",
  },
  PLATINUM: {
    circle: "bg-purple-100",
    icon: "text-purple-500",
    text: "text-purple-700",
    bar: "bg-purple-500",
    row: "text-purple-600",
  },
};

function percent(current: number, target: number) {
  return Math.min(100, Math.round((current / target) * 1000) / 10);
}

// 현재 등급 요약 카드: 게이지 = acceptedCount / nextGradeMin
function SummaryCard({ info }: { info: GradeInfo }) {
  const style = MEDAL_STYLE[info.grade];
  const isMax = info.nextGrade === null || info.nextGradeMin === null;
  const progress = isMax ? 100 : percent(info.acceptedCount, info.nextGradeMin as number);
  return (
    <section className="brutal-card p-6 md:p-8 rounded-xl bg-white" data-purpose="current-rank-summary">
      <div className="flex flex-col md:flex-row items-center gap-6 md:gap-8">
        <div className="relative flex-shrink-0">
          <div
            className={`w-24 h-24 rounded-full ${style.circle} brutal-border flex flex-col items-center justify-center shadow-brutal-sm`}
          >
            <i className={`fa-solid fa-medal text-3xl ${style.icon} mb-1`}></i>
            <span className={`text-xs font-black tracking-wider ${style.text}`}>{info.grade}</span>
          </div>
          <span
            className="absolute -bottom-1 -right-1 bg-amber-400 brutal-border text-[10px] font-black px-1.5 py-0.5 rounded shadow-brutal-sm"
            data-field="level"
          >
            LV.{gradeLevel(info.grade)}
          </span>
        </div>

        <div className="flex-1 w-full space-y-3">
          <div className="flex flex-wrap items-baseline justify-between gap-2">
            <h2 className="text-xl md:text-2xl font-extrabold text-slate-900">
              {"현재 등급 : "}
              <span className="text-blue-600" data-field="gradeName">
                {GRADE_NAME[info.grade]}
              </span>
            </h2>
            <div className="text-base font-bold text-slate-700">
              {"채택된 답변 : "}
              <span className="text-lg font-black text-slate-900" data-field="acceptedCount">
                {info.acceptedCount}개
              </span>
            </div>
          </div>

          <div className="space-y-1.5" data-purpose="level-progress-bar">
            <div className="flex justify-between items-center text-xs font-bold text-slate-500">
              <span data-field="progressText">{isMax ? "최고 등급 달성" : `다음 승급까지 ${progress}% 달성`}</span>
              <span className="text-slate-800 font-extrabold" data-field="progressCount">
                {isMax ? `${info.acceptedCount}개` : `${info.acceptedCount} / ${info.nextGradeMin}`}
              </span>
            </div>
            <div className="w-full h-5 bg-slate-100 brutal-border rounded-full p-0.5 overflow-hidden shadow-inner flex items-center">
              <div
                className={`h-full ${style.bar} rounded-full transition-all duration-500 border-r-2 border-slate-900`}
                data-field="progressBar"
                style={{ width: `${progress}%` }}
              ></div>
            </div>
            <p className="text-xs font-semibold text-slate-500 flex items-center gap-1.5 pt-0.5" data-field="remain">
              <i className="fa-solid fa-circle-info text-amber-500"></i>
              {/* flex 안에서 글자 조각마다 간격이 생기지 않도록 문장을 span 하나로 묶는다 */}
              {isMax ? (
                <span>가장 높은 등급이에요. 앞으로도 좋은 답변 부탁드려요!</span>
              ) : (
                <span>
                  {"다음 등급("}
                  <span className="font-bold text-amber-600">{GRADE_NAME[info.nextGrade as Grade]}</span>
                  {")까지 채택 "}
                  <span className="font-bold text-slate-800">
                    {(info.nextGradeMin as number) - info.acceptedCount}개
                  </span>
                  {" 남음"}
                </span>
              )}
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

// 등급 안내 표: 현재 등급을 하이라이트한다. 시안의 "혜택 예시" 칸은 기능이 없어 뺐다.
function GradeTable({ current }: { current: Grade }) {
  return (
    <section className="brutal-card p-6 rounded-xl flex flex-col justify-between" data-purpose="grade-info-table-card">
      <div>
        <h3 className="text-lg font-bold text-slate-900 mb-4 flex items-center gap-2">
          <i className="fa-solid fa-award text-amber-500"></i>
          {" 등급 안내 "}
        </h3>
        <div className="overflow-hidden brutal-border rounded-lg">
          <table className="w-full text-center text-xs md:text-sm border-collapse" id="grade-table">
            <thead className="bg-slate-100 brutal-border border-b-2 font-bold text-slate-700">
              <tr>
                <th className="py-2.5 px-3 border-r-2 border-slate-900">등급</th>
                <th className="py-2.5 px-3">필요 채택 수</th>
              </tr>
            </thead>
            <tbody className="divide-y-2 divide-slate-900 font-medium">
              {GRADE_ORDER.map((grade) =>
                grade === current ? (
                  <tr className="bg-blue-50/90 font-bold border-y-2 border-blue-600" data-current="true" key={grade}>
                    <td className="py-2.5 px-3 border-r-2 border-slate-900 text-blue-700">
                      <span className="inline-flex items-center justify-center gap-1">
                        {GRADE_NAME[grade]}
                        <span className="text-[10px] bg-blue-600 text-white px-1 rounded">현재</span>
                      </span>
                    </td>
                    <td className="py-2.5 px-3 text-blue-900 font-extrabold">채택 {GRADE_MIN_ACCEPTED[grade]}개 ~</td>
                  </tr>
                ) : (
                  <tr className="hover:bg-slate-50" key={grade}>
                    <td className={`py-2.5 px-3 border-r-2 border-slate-900 font-bold ${MEDAL_STYLE[grade].row}`}>
                      {GRADE_NAME[grade]}
                    </td>
                    <td className="py-2.5 px-3">채택 {GRADE_MIN_ACCEPTED[grade]}개 ~</td>
                  </tr>
                ),
              )}
            </tbody>
          </table>
        </div>
      </div>
      <p className="text-xs text-slate-400 mt-3 font-semibold">※ 현재 등급은 하이라이트 표기됩니다.</p>
    </section>
  );
}

function BadgeIcon({ badge, size }: { badge: Badge; size: "sm" | "lg" }) {
  const box = size === "sm" ? "w-16 h-16 text-xl" : "w-14 h-14 text-2xl";
  return badge.acquired ? (
    <div className={`${box} rounded-full bg-slate-300 brutal-border shadow-brutal-sm flex items-center justify-center`}>
      <i className={`fa-solid ${BADGE_ICON[badge.code].fa} text-slate-700`}></i>
    </div>
  ) : (
    <div
      className={`${box} rounded-full bg-white border-2 border-dashed border-slate-400 flex items-center justify-center`}
    >
      <i className={`fa-solid ${BADGE_ICON[badge.code].fa} text-slate-300`}></i>
    </div>
  );
}

// 뱃지 상세: 획득 조건과 진행도 (REQ-MYPAGE-005 "뱃지 클릭 시 획득 조건 표시")
function BadgeDetail({ badge, onClose }: { badge: Badge; onClose: () => void }) {
  return (
    <div
      className="lg:col-span-5 bg-white brutal-border shadow-brutal p-5 rounded-xl space-y-4"
      data-purpose="badge-detail-modal-card"
    >
      <div className="flex items-center gap-4">
        <div className="flex-shrink-0">
          <BadgeIcon badge={badge} size="lg" />
        </div>
        <div>
          <div className="flex items-center gap-2">
            <h4 className="text-base font-extrabold text-slate-900" data-field="detailName">
              {badge.name}
            </h4>
            {badge.acquired ? (
              <span className="text-[11px] font-bold px-1.5 py-0.5 bg-emerald-100 text-emerald-800 rounded border border-emerald-300">
                획득완료
              </span>
            ) : (
              <span className="text-[11px] font-bold px-1.5 py-0.5 bg-slate-100 text-slate-600 rounded border border-slate-300">
                미획득
              </span>
            )}
          </div>
        </div>
      </div>
      <div className="bg-slate-50 p-3 brutal-border rounded-lg space-y-2">
        <div className="text-xs font-bold text-slate-800" data-field="detailCondition">
          획득 조건 : {badge.condition}
        </div>
        <div>
          <div className="flex justify-between text-[11px] font-bold text-slate-500 mb-1">
            <span>진행도</span>
            <span data-field="detailProgress">
              {Math.min(badge.current, badge.target)} / {badge.target}
            </span>
          </div>
          <div className="w-full h-2.5 bg-slate-200 rounded-full overflow-hidden border border-slate-900">
            <div
              className={`h-full ${badge.acquired ? "bg-emerald-500" : "bg-blue-500"}`}
              style={{ width: `${percent(badge.current, badge.target)}%` }}
            ></div>
          </div>
        </div>
      </div>
      <div className="flex justify-end pt-1">
        <button
          className="px-5 py-2 bg-slate-100 brutal-border shadow-brutal-sm font-bold text-xs hover:bg-slate-200 transition-colors"
          onClick={onClose}
          type="button"
        >
          닫기
        </button>
      </div>
    </div>
  );
}

function BadgeSection({ badges }: { badges: Badge[] }) {
  const [selected, setSelected] = useState<Badge | null>(null);
  const acquired = badges.filter((b) => b.acquired).length;
  return (
    <section className="brutal-card p-6 md:p-8 rounded-xl relative" data-purpose="badges-container">
      <div className="flex items-center justify-between mb-8 pb-3 border-b-2 border-slate-900">
        <div className="flex items-baseline gap-3">
          <h3 className="text-xl font-extrabold text-slate-900">뱃지 목록</h3>
          <span
            className="text-sm font-bold text-slate-600 bg-slate-100 px-2 py-0.5 brutal-border rounded-md"
            data-field="badgeCount"
          >
            획득 {acquired} / 전체 {badges.length}
          </span>
        </div>
        <span className="text-xs text-slate-500 hidden sm:inline">뱃지를 클릭하면 상세 조건을 확인할 수 있습니다</span>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 items-start">
        <div className="lg:col-span-7 grid grid-cols-3 gap-y-8 gap-x-3 text-center" data-purpose="badge-icons-grid">
          {badges.map((badge) => {
            const isSelected = selected?.code === badge.code;
            return (
              <button
                aria-pressed={isSelected}
                className={`flex flex-col items-center group cursor-pointer ${
                  badge.acquired ? "" : "opacity-70 hover:opacity-100 transition-opacity"
                }`}
                data-acquired={badge.acquired}
                data-code={badge.code}
                key={badge.code}
                onClick={() => setSelected(isSelected ? null : badge)}
                type="button"
              >
                <div
                  className={`rounded-full group-hover:-translate-y-1 transition-transform ${
                    isSelected ? "ring-4 ring-blue-400/50" : ""
                  }`}
                >
                  <BadgeIcon badge={badge} size="sm" />
                </div>
                <span
                  className={`mt-2 text-xs ${
                    isSelected
                      ? "font-black text-blue-700"
                      : badge.acquired
                        ? "font-bold text-slate-800"
                        : "font-medium text-slate-500"
                  }`}
                >
                  {badge.name}
                </span>
              </button>
            );
          })}
        </div>

        {selected ? (
          <BadgeDetail badge={selected} onClose={() => setSelected(null)} />
        ) : (
          <div className="lg:col-span-5 border-2 border-dashed border-slate-300 rounded-xl p-6 text-center text-sm font-semibold text-slate-400">
            뱃지를 선택하면 획득 조건과 진행도가 여기에 표시돼요.
          </div>
        )}
      </div>
    </section>
  );
}

export default function GradesBadges() {
  const navigate = useNavigate();
  const { user, initializing } = useAuth();
  const [info, setInfo] = useState<GradeInfo | null>(null);
  const [loadError, setLoadError] = useState<string | null>(null);

  // 로그인이 필요한 화면이다. 새로고침 직후에는 reissue로 로그인 상태를 복구할 때까지 기다린다.
  useEffect(() => {
    if (!initializing && !user) {
      navigate("/login", { replace: true });
    }
  }, [initializing, user, navigate]);

  const loggedIn = user !== null;
  useEffect(() => {
    if (!loggedIn) return;
    let cancelled = false;
    getMyGrade()
      .then((result) => {
        if (!cancelled) setInfo(result);
      })
      .catch((error) => {
        if (!cancelled) setLoadError(getErrorMessage(error, "등급 정보를 불러오지 못했습니다."));
      });
    return () => {
      cancelled = true;
    };
  }, [loggedIn]);

  return (
    <div id="page-grades-badges">
      <style>{css}</style>
      <div
        className="text-slate-900 min-h-screen flex flex-col items-center"
        style={{
          backgroundColor: "rgb(255, 253, 245)",
          backgroundImage: "radial-gradient(rgb(217, 212, 195) 1px, transparent 1px)",
          backgroundSize: "18px 18px",
        }}
      >
        {/* BEGIN: MainContainer */}
        <Header />
        <main className="w-full max-w-5xl space-y-6 p-4 md:p-8" data-purpose="page-wrapper">
          {/* BEGIN: HeaderSection */}
          <header className="flex items-center justify-between pb-2" data-purpose="top-navigation-header">
            <div className="flex items-center space-x-3">
              <div className="w-4 h-8 bg-amber-400 brutal-border shadow-brutal-sm"></div>
              <h1 className="text-2xl md:text-3xl font-black tracking-tight text-slate-900">등급 및 뱃지</h1>
            </div>
            <Link
              className="inline-flex items-center gap-2 px-4 py-2 bg-[#FFFDF5] border-[2.5px] border-[#111111] rounded-[8px] shadow-[3px_3px_0_#111111] hover:translate-x-0.5 hover:translate-y-0.5 hover:shadow-none transition-all font-black text-sm text-[#111111]"
              to="/mypage"
            >
              <i className="fa-solid fa-arrow-left"></i> <span>마이페이지</span>
            </Link>
          </header>
          {/* END: HeaderSection */}

          {loadError && (
            <div className="brutal-card p-4 rounded-xl bg-rose-50 text-sm font-bold text-rose-700" role="alert">
              {loadError}
            </div>
          )}
          {!info && !loadError && (
            <p className="text-sm font-semibold text-slate-500">등급 정보를 불러오는 중이에요…</p>
          )}

          {info && (
            <>
              <SummaryCard info={info} />
              <GradeTable current={info.grade} />
              <BadgeSection badges={info.badges} />
            </>
          )}
        </main>
        {/* END: MainContainer */}
      </div>
    </div>
  );
}
